// XAML resource dictionaries for a native Windows (WinUI 3) library: Colors.xaml with Light and Dark theme
// dictionaries, and Metrics.xaml with sizes as doubles, radii as CornerRadius and each component's measurements.
import { argbHex, parseShadow, parseTokenColor } from "./color";
import { pascalName, resolved, type Mode, type Tokens } from "./model";

const OPEN = [
  "<!-- Generated by `bun run ui:tokens` from ui/design-tokens; do not edit. -->",
  "<ResourceDictionary",
  "    xmlns=\"http://schemas.microsoft.com/winfx/2006/xaml/presentation\"",
  "    xmlns:x=\"http://schemas.microsoft.com/winfx/2006/xaml\">",
];

function themeDictionary(tokens: Tokens, mode: Mode): string[] {
  const key = mode === "light" ? "Light" : "Dark";
  const lines = [`        <ResourceDictionary x:Key="${key}">`];
  for (const [name, color] of Object.entries(tokens.colors)) {
    lines.push(`            <Color x:Key="Gm${pascalName(name)}">${argbHex(parseTokenColor(color[mode]))}</Color>`);
  }
  for (const [name, shadow] of Object.entries(tokens.shadows)) {
    const parsed = parseShadow(shadow[mode]);
    lines.push(`            <Color x:Key="GmShadow${pascalName(name)}Color">${argbHex(parsed.color)}</Color>`);
  }
  lines.push("        </ResourceDictionary>");
  return lines;
}

export function colorsXaml(tokens: Tokens): string {
  return [
    ...OPEN,
    "    <ResourceDictionary.ThemeDictionaries>",
    ...themeDictionary(tokens, "light"),
    ...themeDictionary(tokens, "dark"),
    "    </ResourceDictionary.ThemeDictionaries>",
    "</ResourceDictionary>",
    "",
  ].join("\n");
}

export function metricsXaml(tokens: Tokens): string {
  const lines = [...OPEN];
  for (const [scale, values] of Object.entries(tokens.scales)) {
    for (const [name, value] of Object.entries(values)) {
      const key = `Gm${pascalName(scale)}${pascalName(name)}`;
      if (scale === "radius") {
        lines.push(`    <CornerRadius x:Key="${key}">${value}</CornerRadius>`);
      } else if (scale === "fontWeight" || (scale === "grid" && name === "columns")) {
        lines.push(`    <x:Int32 x:Key="${key}">${value}</x:Int32>`);
      } else {
        lines.push(`    <x:Double x:Key="${key}">${value}</x:Double>`);
      }
    }
  }
  for (const [name, fonts] of Object.entries(tokens.fonts)) {
    // WinUI takes a comma-separated fallback list; the web-only generic names stay out.
    const webOnly = ["-apple-system", "BlinkMacSystemFont", "sans-serif", "monospace"];
    const list = fonts.filter((font) => !webOnly.includes(font));
    lines.push(`    <FontFamily x:Key="GmFont${pascalName(name)}">${list.join(", ")}</FontFamily>`);
  }
  for (const [name, shadow] of Object.entries(tokens.shadows)) {
    const parsed = parseShadow(shadow.light);
    lines.push(`    <x:Double x:Key="GmShadow${pascalName(name)}OffsetY">${parsed.y}</x:Double>`);
    lines.push(`    <x:Double x:Key="GmShadow${pascalName(name)}Blur">${parsed.blur}</x:Double>`);
  }
  for (const [component, parts] of Object.entries(tokens.components)) {
    for (const [part, value] of Object.entries(parts)) {
      const key = `Gm${pascalName(component)}${pascalName(part)}`;
      lines.push(`    <x:Double x:Key="${key}">${resolved(tokens, value)}</x:Double>`);
    }
  }
  lines.push("</ResourceDictionary>", "");
  return lines.join("\n");
}

/** Typography.xaml: each text style as size, weight, line height, character spacing and case. */
export function typographyXaml(tokens: Tokens): string {
  const lines = [...OPEN];
  for (const [name, style] of Object.entries(tokens.textStyles)) {
    const key = `GmText${pascalName(name)}`;
    lines.push(
      `    <x:Double x:Key="${key}Size">${style.size}</x:Double>`,
      `    <x:Int32 x:Key="${key}Weight">${style.weight}</x:Int32>`,
      `    <x:Double x:Key="${key}LineHeight">${style.lineHeight ? style.lineHeight * style.size : 0}</x:Double>`,
      // WinUI's CharacterSpacing is in 1/1000 em.
      `    <x:Int32 x:Key="${key}CharacterSpacing">${Math.round(style.letterSpacing * 1000)}</x:Int32>`,
      `    <x:Boolean x:Key="${key}Uppercase">${style.uppercase ? "True" : "False"}</x:Boolean>`,
    );
  }
  lines.push("</ResourceDictionary>", "");
  return lines.join("\n");
}
